// Authenticated graph editing; never loaded as executable code into saved sandboxed views.
window.dtPortEditor={mount(host,{call,identity,onSaved=()=>{},initial,readonly=false,story,selectedPort}={}){
 const E=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c])),types=['http-ingress','http-egress','kafka-consume','kafka-produce','db-read','db-write','scheduled','internal-library'];
 const fields={'http-ingress':['method','host','path','base_path'],'http-egress':['method','host','path','base_path','target_service'],'kafka-consume':['cluster','topic','schema','schema_version'],'kafka-produce':['cluster','topic','schema','schema_version'],'db-read':['db','schema','table','columns'],'db-write':['db','schema','table','columns'],scheduled:['schedule','registration'],'internal-library':['artifact','module','version','target_repo','target_revision','target_signature']};
 const inputTypes=t=>['http-ingress','kafka-consume','scheduled'].includes(t),label=p=>[p.boundary?.method,p.boundary?.path||p.boundary?.topic||p.boundary?.table||p.boundary?.artifact||p.boundary?.registration||p.boundary?.schedule||'Unresolved boundary'].filter(Boolean).join(' ');
 let data=initial; let selected=null; let draft=null; const dirty=new DTState.Dirty(); const pending=new DTState.Activity(); const sequence=new DTState.Revision();
 host.classList.add('ports-workspace');host.innerHTML='<div class="ports-toolbar"><label>Find a port<input data-port-search type="search" placeholder="Route, table, topic or source"></label><label>Type<select data-port-type><option value="">All boundary types</option>'+types.map(t=>'<option>'+E(t)+'</option>').join('')+'</select></label><label><span>Hidden findings</span><input data-port-hidden type="checkbox"></label><button data-port-add>Add port</button><button data-port-reload>Reload</button><span class="ports-summary"></span></div><div class="ports-layout"><div><div class="ports-graph" aria-label="Service boundary graph"></div><p class="ports-mode-note">Inputs and triggers enter on the left. Dependencies and outputs leave on the right. Select a port to inspect or correct it.</p><div class="ports-list" aria-label="Port list"></div></div><section class="port-inspector" aria-label="Selected port"></section></div><p class="ports-notice" role="status" aria-live="polite"></p>';
 const $=s=>host.querySelector(s),notice=(s,error=false)=>{const n=$('.ports-notice');n.textContent=s;n.style.color=error?'var(--bad)':'';},canLeave=()=>!dirty.value||confirm('Discard the unsaved port draft?');
 function currentIdentity(){return typeof identity==='function'?identity():identity||data?.identity;}
 function rows(){const q=$('[data-port-search]').value.toLowerCase(),type=$('[data-port-type]').value;return [...(data?.ports||[]),...($('[data-port-hidden]').checked?(data?.disabled||[]):[])].filter(p=>(!type||p.type===type)&&JSON.stringify(p).toLowerCase().includes(q));}
 function renderGraph(){const all=rows(),shown=all.slice(0,48),left=shown.filter(p=>inputTypes(p.type)),right=shown.filter(p=>!inputTypes(p.type)),height=Math.max(260,Math.max(left.length,right.length)*42+80),mid=height/2,service=data?.identity?.service||currentIdentity()?.service||'Service';
  $('.ports-summary').textContent=all.length+' ports'+(all.length>48?' · 48 graphed':'');
  const node=(p,x,y)=>'<path d="M'+(x<300?250:450)+','+y+' C350,'+y+' 350,'+mid+' 350,'+mid+'" fill="none" stroke="var(--line)"/><g class="port-node" role="button" tabindex="0" aria-label="'+E(p.type+' '+label(p))+'" aria-pressed="'+String(selected===p.id)+'" data-port-id="'+E(p.id)+'"><rect x="'+x+'" y="'+(y-15)+'" width="230" height="30" rx="7"/><text x="'+(x+10)+'" y="'+(y+4)+'">'+E(label(p).slice(0,32))+'<title>'+E(p.type+' · '+label(p))+'</title></text></g>';
  $('.ports-graph').innerHTML='<svg viewBox="0 0 720 '+height+'" role="group" aria-label="'+E(service)+' ports"><text x="20" y="26">Inputs & triggers</text><text x="470" y="26">Dependencies & outputs</text>'+left.map((p,i)=>node(p,20,60+i*42)).join('')+right.map((p,i)=>node(p,470,60+i*42)).join('')+'<rect x="260" y="'+(mid-27)+'" width="200" height="54" rx="9" fill="var(--accent-soft)" stroke="var(--accent)"/><text x="360" y="'+(mid-1)+'" text-anchor="middle">'+E(service)+'</text><text x="360" y="'+(mid+17)+'" text-anchor="middle" style="font-size:10px">'+E(data?.identity?.revision?.slice(0,12)||'Source unresolved')+'</text></svg>';
  $('.ports-list').innerHTML=all.map(p=>'<button class="'+(p.disabled?'port-disabled':'')+'" data-port-id="'+E(p.id)+'" aria-pressed="'+String(selected===p.id)+'"><small>'+E(p.type)+'</small><span>'+E(label(p))+'<small> · '+E(p.status||p.evidence?.origin||'detected')+'</small></span></button>').join('')||'<p class="ports-empty">No matching ports. Add a missing boundary or change the filter.</p>';
  for(const b of host.querySelectorAll('[data-port-id]')){b.onclick=()=>select(b.dataset.portId);if(b.tagName.toLowerCase()==='g')b.onkeydown=e=>{if(e.key==='Enter'||e.key===' '){e.preventDefault();select(b.dataset.portId);}};}
 }
 function select(id){if(!canLeave())return;const p=[...(data?.ports||[]),...(data?.disabled||[])].find(p=>p.id===id);if(id&&!p)return notice('This port is absent from the selected source revision. Reload or select an available boundary.',true);selected=id;draft=structuredClone(p||{type:'http-ingress',boundary:{method:'GET'},handler:{},mappings:[],parameters:[]});dirty.value=false;renderGraph();renderEditor(p);}
 function renderEditor(original){const root=$('.port-inspector'),p=draft;if(!p){root.innerHTML='<div class="ports-empty"><h3>Inspect a boundary</h3>Select a port in the graph or list. Review its source, correct a false target, or add a missing connection.</div>';return;}
  const manual=!data?.detected?.some(p=>p.id===selected),disabled=!!original?.disabled;
  root.innerHTML='<h3>'+(selected?'Edit '+E(p.type):'Add a missing port')+'</h3><p>'+E(data?.identity?.repo||'Repository unresolved')+' · '+E(data?.identity?.revision?.slice(0,12)||'Revision unresolved')+'<br>'+E(original?.evidence?.origin||'Manual declaration')+' · changes stay in this chat/task overlay</p><div class="port-fields"><label>Boundary type<select data-p-type>'+types.map(t=>'<option '+(t===p.type?'selected':'')+'>'+E(t)+'</option>').join('')+'</select></label><label>Handler signature<input data-p-handler="signature" value="'+E(p.handler?.signature)+'" placeholder="OrderController#create(Request)"></label><label>Source file<input data-p-handler="file" value="'+E(p.handler?.file)+'" placeholder="src/main/java/OrderController.java"></label><label>Source line<input type="number" min="1" data-p-handler="line" value="'+E(p.handler?.line)+'"></label>'+fields[p.type].map(k=>'<label>'+E(k.replaceAll('_',' '))+'<input data-p-boundary="'+k+'" value="'+E(Array.isArray(p.boundary[k])?p.boundary[k].join(', '):p.boundary[k])+'" placeholder="'+E(k==='path'?'/orders/{id}':k==='host'?'api.dev.example':'Unresolved')+'"></label>').join('')+'</div><details class="ports-advanced"><summary>Field mappings ('+(p.mappings||[]).length+')</summary><div data-p-mappings></div><button data-p-map-add>Add field mapping</button></details><label class="port-reason">Reason or source citation<textarea data-p-reason placeholder="Why is this connection being added or corrected?"></textarea></label><div class="port-actions"><button class="port-primary" data-p-save>'+(selected?'Save correction':'Add port')+'</button><button data-p-cancel>Cancel draft</button>'+(selected?'<button class="port-danger" data-p-hide>'+(manual?'Delete manual port':disabled?'Restore detection':'Hide false detection')+'</button>'+(!manual&&!disabled&&original?.evidence?.origin==='manual'?'<button data-p-restore>Restore original</button>':''):'')+'</div><p class="ports-mode-note">Detected source stays intact. Corrections are revisioned declarations, not runtime or Joern proof.</p><details class="ports-advanced"><summary>Exact identity, source & audit history</summary><pre>'+E(JSON.stringify({identity:data?.identity,adjustmentRevision:data?.revision,port:original,history:data?.history},null,2))+'</pre></details>';
  const update=()=>{dirty.value=true;};for(const i of root.querySelectorAll('input,textarea'))i.addEventListener('input',update);
  root.querySelector('[data-p-type]').onchange=e=>{readDraft();draft.type=e.target.value;draft.boundary={};dirty.value=true;renderEditor(original);};
  function mappings(){root.querySelector('[data-p-mappings]').innerHTML=(p.mappings||[]).map((m,i)=>'<div class="port-mapping"><input data-map="'+i+'" data-key="from" aria-label="Mapping source" placeholder="request.total" value="'+E(m.from)+'"><input data-map="'+i+'" data-key="to" aria-label="Mapping target" placeholder="record.total" value="'+E(m.to)+'"><select data-map="'+i+'" data-key="direction" aria-label="Mapping direction">'+['request','response','read','write','argument','return','control'].map(d=>'<option '+(d===m.direction?'selected':'')+'>'+d+'</option>').join('')+'</select><button data-map-remove="'+i+'" aria-label="Remove mapping">×</button></div>').join('');for(const input of root.querySelectorAll('[data-map]'))input.oninput=()=>{p.mappings[Number(input.dataset.map)][input.dataset.key]=input.value;dirty.value=true;};for(const b of root.querySelectorAll('[data-map-remove]'))b.onclick=()=>{p.mappings.splice(Number(b.dataset.mapRemove),1);dirty.value=true;mappings();};}
  mappings();root.querySelector('[data-p-map-add]').onclick=()=>{p.mappings.push({from:'',to:'',direction:'request'});dirty.value=true;mappings();};
  root.querySelector('[data-p-cancel]').onclick=()=>{if(canLeave()){dirty.value=false;selected=null;draft=null;renderGraph();renderEditor();}};
  root.querySelector('[data-p-save]').onclick=()=>save(selected?'correct':'add');
  if(selected)root.querySelector('[data-p-hide]').onclick=()=>save(manual?'remove':disabled?'restore':'disable');
  if(root.querySelector('[data-p-restore]'))root.querySelector('[data-p-restore]').onclick=()=>save('restore');
  for(const el of root.querySelectorAll('input,select,textarea,button'))el.disabled=readonly||pending.value;
  if(p.type.startsWith('http-')){const a=document.createElement('a');a.textContent='Open request in API explorer';a.href='/api-client?'+new URLSearchParams({method:p.boundary.method||'GET',path:p.boundary.path||'',host:p.boundary.host||'',service:data.identity.service,...(story?{story:typeof story==='function'?story():story}:{})});a.target='_blank';a.rel='noopener';root.append(a);}
 }
 function readDraft(){if(!draft)return;for(const input of host.querySelectorAll('[data-p-handler]'))draft.handler[input.dataset.pHandler]=input.dataset.pHandler==='line'?input.value?Number(input.value):null:input.value||null;for(const input of host.querySelectorAll('[data-p-boundary]'))draft.boundary[input.dataset.pBoundary]=input.dataset.pBoundary==='columns'?input.value.split(',').map(x=>x.trim()).filter(Boolean):input.dataset.pBoundary==='base_path'?input.value:input.value||null;}
 async function save(action){if(readonly||pending.value)return;const reason=$('[data-p-reason]').value.trim();if(!reason)return notice('Add a reason or source citation before saving.',true);readDraft();const port={type:draft.type,handler:draft.handler,boundary:draft.boundary,mappings:draft.mappings||[],parameters:draft.parameters||[]},operation={action,...(selected?{port_id:selected}:{}),...(['add','correct'].includes(action)?{port}:{})};pending.value=true;for(const b of host.querySelectorAll('button,input,select,textarea'))b.disabled=true;notice('Saving revisioned correction…');try{data=await call('passport_adjust',{...currentIdentity(),expected_revision:data.revision??null,reason,operations:[operation]});dirty.value=false;selected=null;draft=null;onSaved(data);renderGraph();renderEditor();notice('Saved. Detected evidence and correction history are preserved.');}catch(e){notice(e.message+' Your draft is preserved. Reload if the revision changed.',true);}finally{pending.value=false;for(const b of host.querySelectorAll('button,input,select,textarea'))b.disabled=readonly;}}
 async function load(){if(!canLeave())return;const n=++sequence.value;notice('Reading exact source and adjustments…');try{const result=await call('passport_adjustments',currentIdentity());if(n!==sequence.value)return;data=result;selected=null;draft=null;dirty.value=false;renderGraph();renderEditor();notice((data.ports||[]).length+' ports · '+(data.gaps||[]).length+' source gaps');if(selectedPort){select(selectedPort);selectedPort=null;}}catch(e){notice(e.message,true);}}
 for(const input of host.querySelectorAll('[data-port-search],[data-port-type],[data-port-hidden]'))input.oninput=renderGraph;
 $('[data-port-add]').onclick=()=>select(null);$('[data-port-reload]').onclick=load;$('[data-port-add]').disabled=readonly;
 if(data){renderGraph();renderEditor();if(selectedPort)select(selectedPort);}else load();
 return{load,dirty:()=>dirty.value,pending:()=>pending.value,select,destroy:()=>{sequence.value++;host.replaceChildren();}};
}};
